mapper.update:
UPDATE
       RECIPES
   SET
       RECIPE_TITLE     = #{recipeTitle}
    ,  RECIPE_INFO      = #{recipeInfo}
    ,  RECIPE_MAIN_IMG  = #{recipeMainImg}
    ,  RECIPES_IMG_PATH = #{recipesImgPath}
 WHERE
       RECIPE_NO = #{recipeNo}
   AND DEL_YN    = 'N'

UPDATE
       MATERIAL
   SET
       MATERIAL_NAME = #{materialName}
    ,  AMOUNT        = #{amount}
 WHERE
       MATERIAL_NO = #{materialNo}

UPDATE
       RECIPE_STEPS
   SET
       STEP_INFO     = #{stepInfo}
    ,  STEP_IMG      = #{stepImg, jdbcType=VARCHAR}
    ,  STEP_ORDER    = #{stepOrder}
    ,  STEP_IMG_PATH = #{stepImgPath, jdbcType=VARCHAR}
 WHERE
       STEP_NO = #{stepNo}
